questionvariables.text:
/* PARSONS_GENERATED_BEGIN */
stack_include_contrib("prooflib.mac");
stack_include("https://yositomi-opu.github.io/stack_questions/multilang_library.mac");
%__prt_get(L,s):=block([r:"",x],for x in L do if first(x)=s then r:second(x),r);
%__mcq_lang(L,s):=block([r],r:%__prt_get(L,s),if r="" then r:%__prt_get(L,"en"),if r="" and length(L)>0 then r:second(first(L)),r);

%_pp_q:%__mcq_lang([["ja", castext("偶数と偶数の和が偶数となる証明を完成させなさい。")], ["en", castext("Complete a proof that the sum of two even integers is even.")]], %_STACK_LANG);
%_pp_s0:%__mcq_lang([["ja", castext("\\(a=2m,\\ b=2n\\) とおく（\\(m,n\\) は整数）。")], ["en", castext("Write \\(a=2m,\\ b=2n\\), with integers \\(m,n\\).")]], %_STACK_LANG);
%_pp_s1:%__mcq_lang([["ja", castext("\\(a+b=2(m+n)\\) となる。")], ["en", castext("Then \\(a+b=2(m+n)\\).")]], %_STACK_LANG);
%_pp_s2:%__mcq_lang([["ja", castext("\\(m+n\\) は整数なので、\\(a+b\\) は偶数である。")], ["en", castext("Since \\(m+n\\) is an integer, \\(a+b\\) is even.")]], %_STACK_LANG);
%_pp_s3:%__mcq_lang([["ja", castext("結論を述べる。")], ["en", castext("State the conclusion.")]], %_STACK_LANG);
%_pp_s4:%__mcq_lang([["ja", castext("偶数どうしの和は奇数である。")], ["en", castext("The sum of two even integers is odd.")]], %_STACK_LANG);
proof_steps:random_permutation([["s1", %_pp_s0], ["s2", %_pp_s1], ["s3", %_pp_s2], ["s4", %_pp_s3], ["unused", %_pp_s4]]);
proof_steps_ja:proof_steps;
proof_steps_en:proof_steps;
ta:proof("s1", "s2", "s3", "s4");
ta_flat:ta;
%_pp_alts:[proof("s1", "s2", "s3", "s4"), proof("s1", "s3", "s2", "s4")];
%_pp_orders:setify(map(proof_flatten,%_pp_alts));
tdag:[["s1", "s2", "s4"], ["s1", "s3", "s4"]];
%_pp_true_text:[["ja", "正しい証明です。"], ["en", "Correct proof."]];
%_pp_false_text:[["ja", "誤答の確認：{@length(saa)@}"], ["en", "Review the response: {@length(saa)@}"]];
/* PARSONS_GENERATED_END */
/* PRT_TEMPLATE_WEBAPP_V1
